package dev.exodus.teleporter.domain;import org.junit.jupiter.api.Test;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;class DroppedComponentPolicyTest{@Test void currentItemsPersistAndStaleItemsDisappear(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();assertEquals(DroppedComponentPolicy.Action.PROTECT,DroppedComponentPolicy.action(a,a));assertEquals(DroppedComponentPolicy.Action.REMOVE,DroppedComponentPolicy.action(a,b));assertEquals(DroppedComponentPolicy.Action.REMOVE,DroppedComponentPolicy.action(a,null));}@Test void voidItemsReturnToLastSafePosition(){assertTrue(DroppedComponentPolicy.shouldReturnFromVoid(-65,-64,true));assertFalse(DroppedComponentPolicy.shouldReturnFromVoid(10,-64,true));assertFalse(DroppedComponentPolicy.shouldReturnFromVoid(-65,-64,false));}}
